function intersect(a, b) {
  const result = new Set();
  for (const x of a) {
    if (b.has(x)) result.add(x);
  }
  return result;
}

const rice = new Set(["ada", "bola", "chidi"]);
const oil = new Set(["bola", "chidi", "dayo"]);
console.log(intersect(rice, oil));

