function checkAccess(held, required) {
  if (required.size === 0) return "refused: nothing required";
  const missing = required.difference(held);
  if (missing.size > 0) return `refused: missing ${[...missing].join(", ")}`;
  return "allowed";
}

const held = new Set(["orders:read", "orders:refund"]);
console.log(checkAccess(held, new Set(["orders:refund"])));
console.log(checkAccess(held, new Set(["orders:read", "orders:delete", "reports:read"])));
console.log(checkAccess(held, new Set()));

