const rolePermissions = {
  support: new Set(["orders:read", "customers:read"]),
  warehouse: new Set(["orders:read", "stock:read", "stock:update"]),
};

function permissionsOf(roles) {
  let held = new Set();
  for (const role of roles) {
    const granted = rolePermissions[role];
    if (!granted) continue;
    held = held.union(granted);
  }
  return held;
}

console.log(permissionsOf(["support", "warehouse", "suport"]).size);

