questions.solution:
function similarity(a, b) {
  const all = a.union(b);
  if (all.size === 0) return 0;
  return a.intersection(b).size / all.size;
}

const cooker = new Set(["kitchen", "electric", "cooking"]);
const kettle = new Set(["kitchen", "electric", "drinks"]);
console.log(similarity(cooker, kettle));
console.log(similarity(new Set(), new Set()));

